{"implementation": "def solve(case):
    items = case['items']
    required = set(case['required_failure_items'])
    reduced = list(items)
    attempts = 0
    i = 0
    while i < len(reduced):
        item = reduced[i]
        if item not in required:
            reduced.pop(i)
            attempts += 1
        else:
            i += 1
    one_minimal = len(reduced) == 1
    return {
        "attempts": attempts,
        "one_minimal": one_minimal,
        "reduced_items": reduced
    }"}
